-- Municípios do IBGE com coordenadas (fonte: github.com/kelvins/municipios-brasileiros, licença MIT).
-- Usado pelo rodízio de leads para achar o corretor mais próximo.
create table if not exists public.municipios (codigo_ibge int primary key, nome text not null, uf char(2) not null, chave text not null, latitude float8 not null, longitude float8 not null);
create index if not exists municipios_uf_chave on public.municipios (uf, chave);
alter table public.municipios enable row level security;
drop policy if exists municipios_le on public.municipios;
create policy municipios_le on public.municipios for select using (true);
